import { prompt, type HostGitHubClient } from "@grok/agent-sdk";
import type { GitHubPrRef } from "@grok/agent-sdk/channels/github";

const MAX_DIFF_CHARS = 150_000;

export async function loadPrFiles(args: {
  github: HostGitHubClient;
  ref: GitHubPrRef;
}): Promise<Record<string, string> | undefined> {
  try {
    const octokit = await args.github.getOctokit();
    const pull = {
      owner: args.ref.owner,
      repo: args.ref.repo,
      pull_number: args.ref.number,
    };
    const [meta, diff] = await Promise.all([
      octokit.rest.pulls.get(pull),
      octokit.rest.pulls.get({ ...pull, mediaType: { format: "diff" } }),
    ]);
    const data = meta.data;
    const text = typeof diff.data === "string" ? diff.data : "";
    const header = prompt`
      # ${data.title}

      url: ${args.ref.url}
      author: @${data.user?.login ?? "unknown"}
      head: ${data.head.ref} (${data.head.sha})
      base: ${data.base.ref}
    `;
    return {
      "pr/meta.md": `${header}\n\n${data.body ?? ""}`,
      "pr/diff.patch":
        text.length > MAX_DIFF_CHARS ? `${text.slice(0, MAX_DIFF_CHARS)}\n…[truncated]\n` : text,
      "pr/head.sha": data.head.sha,
    };
  } catch {
    return undefined;
  }
}
